*** Begin Patch
*** Update File: D:/Users/Eric Liu/Documents/Paradox Interactive/Victoria 3/nesnd-workbench/exports/canon-route-execution-20261104-a/common/scripted_triggers/nesnd_american_restoration.txt
@@
 nesnd_mexican_restoration_host = { c:MEX ?= this NOT = { has_variable = nesnd_restoration_local_closed } NOT = { has_global_variable = nesnd_mexican_restoration_resolved } NOT = { has_global_variable = nesnd_mexican_restoration_case_started } }
 nesnd_andean_restoration_host = {
- OR = { c:PEU ?= this c:NPU ?= this c:SPU ?= this }
- NOT = { has_variable = nesnd_restoration_local_closed }
+ nesnd_andean_restoration_country = yes
  NOT = { has_global_variable = nesnd_andean_restoration_resolved }
- OR = { NOT = { has_global_variable = nesnd_andean_restoration_case_started } c:TWT ?= { has_variable = nesnd_restoration_rebel } }
- any_scope_state = { state_population > 0 state_region = { is_in_geographic_region = geographic_region_peru } }
+ NOT = { has_global_variable = nesnd_andean_restoration_case_started }
+ NOT = { exists = c:TWT }
 }
 nesnd_american_restoration_host = {
  is_country_alive = yes
@@
  nesnd_restoration_native_state = yes state_population >= 200000 nesnd_restoration_core_share >= 0.4 nesnd_restoration_single_remaining >= 150000
 }
 nesnd_restoration_can_recognize = {
- nesnd_american_restoration_host = yes government_legitimacy >= 50 ig:ig_rural_folk = { is_in_government = yes }
+ government_legitimacy >= 50 ig:ig_rural_folk = { is_in_government = yes }
  NOT = { nesnd_restoration_pair_at_war = yes }
- trigger_if = { limit = { c:MEX ?= this } NOT = { exists = c:NAH } }
- trigger_else = { OR = {
-  NOT = { exists = c:TWT }
-  AND = { c:TWT ?= { has_variable = nesnd_restoration_rebel is_country_alive = yes is_subject = no } is_subject = no NOT = { has_variable = nesnd_restoration_request_cooldown } NOT = { has_variable = nesnd_restoration_invitation_pending } }
- } }
+ trigger_if = { limit = { nesnd_restoration_invitation_applicant = yes }
+  is_subject = no NOT = { is_at_war = yes }
+  c:TWT = { is_subject = no NOT = { is_at_war = yes } }
+  NOT = { has_variable = nesnd_restoration_request_cooldown } NOT = { has_variable = nesnd_restoration_invitation_pending }
+ }
+ trigger_else = {
+  nesnd_american_restoration_host = yes
+  trigger_if = { limit = { c:MEX ?= this } NOT = { exists = c:NAH } }
+  trigger_else = { NOT = { exists = c:TWT } }
+ }
 }
 nesnd_restoration_can_negotiate = {
  nesnd_american_restoration_host = yes government_legitimacy >= 50
@@
 }

 nesnd_restoration_invitation_live = {
- c:TWT ?= this has_variable = nesnd_restoration_rebel is_country_alive = yes is_subject = no NOT = { is_at_war = yes }
- trigger_if = { limit = { exists = scope:nesnd_restoration_applicant exists = scope:nesnd_restoration_request_epoch }
+ nesnd_restoration_existing_court = yes is_subject = no NOT = { is_at_war = yes }
+ trigger_if = { limit = { exists = scope:nesnd_restoration_applicant exists = scope:nesnd_restoration_request_epoch exists = scope:nesnd_restoration_requested_court exists = scope:nesnd_restoration_court_epoch has_variable = nesnd_restoration_epoch }
+  this = scope:nesnd_restoration_requested_court
+  var:nesnd_restoration_epoch = scope:nesnd_restoration_court_epoch
   scope:nesnd_restoration_applicant = {
-   is_country_alive = yes is_subject = no NOT = { is_at_war = yes }
-   nesnd_american_restoration_host = yes government_legitimacy >= 50 ig:ig_rural_folk = { is_in_government = yes }
+   nesnd_restoration_invitation_applicant = yes is_subject = no NOT = { is_at_war = yes }
+   government_legitimacy >= 50 ig:ig_rural_folk = { is_in_government = yes }
    NOT = { nesnd_restoration_pair_at_war = yes }
-   OR = { c:PEU ?= this c:NPU ?= this c:SPU ?= this }
    trigger_if = { limit = { has_variable = nesnd_restoration_invitation_pending has_variable = nesnd_restoration_request_epoch }
     var:nesnd_restoration_request_epoch = scope:nesnd_restoration_request_epoch
    }
@@
  }
  trigger_else = { always = no }
 }
+
+# Country identity and local eligibility are separate from opening a new case.
+nesnd_andean_restoration_country = {
+ is_country_alive = yes OR = { c:PEU ?= this c:NPU ?= this c:SPU ?= this }
+ NOT = { has_variable = nesnd_restoration_local_closed }
+ any_scope_state = { state_population > 0 state_region = { is_in_geographic_region = geographic_region_peru } }
+ any_scope_state = { state_population > 0 any_scope_pop = { culture = { nesnd_hus_native_culture = yes } } }
+}
+nesnd_restoration_existing_court = {
+ c:TWT ?= this is_country_alive = yes has_variable = nesnd_restoration_rebel has_variable = nesnd_a2_restoration_adopted
+ trigger_if = { limit = { has_variable = nesnd_restoration_epoch has_global_variable = nesnd_andean_restoration_case_epoch has_global_variable = nesnd_andean_restoration_case_country }
+  global_var:nesnd_andean_restoration_case_country ?= this
+  var:nesnd_restoration_epoch = global_var:nesnd_andean_restoration_case_epoch
+ }
+ trigger_else = { always = no }
+}
+nesnd_restoration_invitation_applicant = {
+ nesnd_andean_restoration_country = yes
+ trigger_if = { limit = { exists = c:TWT } c:TWT = { nesnd_restoration_existing_court = yes } }
+ trigger_else = { always = no }
+}
+nesnd_restoration_entry_visible = {
+ OR = { nesnd_american_restoration_host = yes nesnd_restoration_invitation_applicant = yes }
+}
*** End Patch

