*** Update File: D:/Users/Eric Liu/Documents/Paradox Interactive/Victoria 3/nesnd-workbench/exports/canon-route-execution-20261104-a/common/scripted_effects/nesnd_american_restoration.txt
@@
    set_variable = { name = nesnd_restoration_invitation_pending days = 90 }
    set_variable = { name = nesnd_restoration_request_cooldown months = 12 }
    save_scope_as = nesnd_restoration_applicant
+   c:TWT = { save_scope_as = nesnd_restoration_requested_court }
+   save_scope_value_as = { name = nesnd_restoration_court_epoch value = c:TWT.var:nesnd_restoration_epoch }
    if = { limit = { NOT = { has_variable = nesnd_restoration_request_epoch } } set_variable = { name = nesnd_restoration_request_epoch value = 0 } }
    change_variable = { name = nesnd_restoration_request_epoch add = 1 }
    save_scope_value_as = { name = nesnd_restoration_request_epoch value = var:nesnd_restoration_request_epoch }
@@
    else = { change_tag = TWT }
    if = { limit = { OR = { c:NAH ?= this c:TWT ?= this } }
     set_variable = nesnd_restoration_rebel set_variable = nesnd_a2_restoration_adopted set_variable = nesnd_restoration_local_closed
+    set_variable = { name = nesnd_restoration_epoch value = 1 }
+    nesnd_restoration_register_court = yes
     nesnd_restoration_identity = yes nesnd_restoration_mark_resolved = yes
     set_variable = nesnd_restoration_victory add_modifier = { name = nesnd_native_restored_rule months = 120 }
     trigger_event = { id = nesnd_american_restoration.4 popup = yes }
@@
  set_variable = nesnd_restoration_rebel set_variable = nesnd_a2_restoration_adopted
  set_variable = { name = nesnd_restoration_epoch value = 1 }
  if = { limit = { c:NAH ?= this } set_global_variable = nesnd_mexican_restoration_case_started }
- else = { set_global_variable = nesnd_andean_restoration_case_started }
+ else = { set_global_variable = nesnd_andean_restoration_case_started nesnd_restoration_register_court = yes }
  set_variable = { name = nesnd_restoration_opponent value = scope:nesnd_restoration_host }
  scope:nesnd_restoration_host = {
   set_variable = nesnd_restoration_war_host set_variable = nesnd_a2_war_adopted set_variable = { name = nesnd_restoration_epoch value = 1 } set_variable = { name = nesnd_restoration_opponent value = prev }
@@
   }
  }
 }
+
+# A once-only case registry binds the real court object, not a reusable TAG.
+nesnd_restoration_register_court = {
+ if = { limit = { c:TWT ?= this has_variable = nesnd_restoration_rebel has_variable = nesnd_a2_restoration_adopted has_variable = nesnd_restoration_epoch }
+  if = { limit = { NOT = { has_global_variable = nesnd_andean_restoration_case_epoch } NOT = { has_global_variable = nesnd_andean_restoration_case_country } }
+   set_global_variable = { name = nesnd_andean_restoration_case_country value = this }
+   set_global_variable = { name = nesnd_andean_restoration_case_epoch value = var:nesnd_restoration_epoch }
+   set_global_variable = nesnd_andean_restoration_case_started
+  }
+ }
+}
*** End Patch

